def Q(topic, number, difficulty, form, tag, question, choices, answer, explain, *quotes, passage=None):
    item = {
        "id": f"ai26-{topic}-{number:02d}", "type": "mc", "unit": 8,
        "topic": topic, "difficulty": difficulty, "format": form, "tag": tag,
        "q": question, "choices": choices, "answer": answer,
        "explain": explain, "quotes": list(quotes),
    }
    if passage:
        item["passage"] = passage
    return item


